using System.Diagnostics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using TextAnalysis;

// Build a reproducible corpus (~10K words)
var rng = new Random(42);
var words = new string[10_000];
for (int i = 0; i < words.Length; i++)
{
    int len = rng.Next(1, 15);
    var chars = new char[len];
    for (int j = 0; j < len; j++)
        chars[j] = (char)('a' + rng.Next(0, 26));
    words[i] = new string(chars);
}
var analyzer = new TextAnalyzer(string.Join(' ', words));

Console.WriteLine($"Runtime: {RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"Words: {analyzer.WordCount}");
Console.WriteLine();

const int WarmupIterations = 500;
const int MeasuredIterations = 5000;

Benchmark("AverageWordLength", () => analyzer.AverageWordLength());
Benchmark("WordLengthHistogram", () => analyzer.WordLengthHistogram());
Benchmark("UniqueWordCount", () => analyzer.UniqueWordCount());

void Benchmark(string name, Action action)
{
    // Warmup
    for (int i = 0; i < WarmupIterations; i++)
        action();

    // Collect samples
    var times = new double[20]; // 20 batches
    int batchSize = MeasuredIterations / times.Length;
    for (int b = 0; b < times.Length; b++)
    {
        var sw = Stopwatch.StartNew();
        for (int i = 0; i < batchSize; i++)
            action();
        sw.Stop();
        times[b] = sw.Elapsed.TotalNanoseconds / batchSize;
    }

    Array.Sort(times);
    // Use trimmed mean (drop top/bottom 20%)
    int trim = times.Length / 5;
    double sum = 0;
    for (int i = trim; i < times.Length - trim; i++)
        sum += times[i];
    double mean = sum / (times.Length - 2 * trim);

    // Median
    double median = times[times.Length / 2];

    // StdDev of trimmed set
    double sq = 0;
    for (int i = trim; i < times.Length - trim; i++)
        sq += (times[i] - mean) * (times[i] - mean);
    double stddev = Math.Sqrt(sq / (times.Length - 2 * trim));

    string unit = "ns";
    double scale = 1;
    if (mean > 1_000_000) { unit = "ms"; scale = 1_000_000; }
    else if (mean > 1_000) { unit = "µs"; scale = 1_000; }

    Console.WriteLine($"{name,-25} mean: {mean/scale,10:F2} {unit}  median: {median/scale,10:F2} {unit}  stddev: {stddev/scale,8:F2} {unit}");
}
